S="C:/Users/ATHARV~1/AppData/Local/Temp/claude/D--Atharva-firstrun/32ae13f1-f15f-4a56-aeb6-6ccded8649e2/scratchpad/nl"; python -c "
import json,datetime as D
t=[x for x in json.load(open('$S/traces.json'))['data']['traces'] if x['traceName']=='firstrun.run' and x['workflowName']=='firstrun']
t.sort(key=lambda x:x['startedAt'])
runs=json.load(open('docs/runs/index.json'))['runs']
def p(s): return D.datetime.fromisoformat(s.replace('Z','+00:00'))
for r in runs: r['_start']=D.datetime.strptime(r['id'][:15],'%Y%m%d-%H%M%S').replace(tzinfo=D.timezone.utc)
used=set()
rows=[]
for x in t:
  st=p(x['startedAt']); best=None
  for r in runs:
    dt=abs((r['_start']-st).total_seconds())
    if dt<90 and r['id'] not in used and (best is None or dt<best[0]): best=(dt,r)
  r=best[1] if best else None
  if r: used.add(r['id'])
  print(x['startedAt'][11:19], x['traceId'][:8], ','.join(x['tags'] or []).ljust(8), x['status'].ljust(5), '%.4f'%x['totalCostUsd'], '%4ds'%(x['durationMs']//1000), x['spansCount'], '|', (r['target'] if r else '-'), (r['status'] if r else '-'), (f\"{r['passed']}/{r['total']}\" if r else ''), (r['cost'] if r else ''))
print('unmatched runs', [r['id'] for r in runs if r['id'] not in used])
"

