import json, subprocess, sys, concurrent.futures as F
S = sys.argv[1]
T = [x for x in json.load(open(S + '/traces.json'))['data']['traces'] if x['traceName'] == 'firstrun.run' and x['workflowName'] == 'firstrun']
def run(args):
    r = subprocess.run('npx -y neatlogs-cli ' + args + ' --json', shell=True, capture_output=True, text=True, encoding='utf-8')
    try: return json.loads(r.stdout)
    except Exception: return None
def spans(t):
    d = run(f"traces spans list {t['traceId']} --limit 100")
    return t, (d or {}).get('data', {}).get('spans', [])
out = []
with F.ThreadPoolExecutor(8) as ex:
    res = list(ex.map(spans, T))
jobs = []
for t, sp in res:
    for s in sp:
        nm = s.get('name') or ''
        if nm.startswith('step.') and s.get('status') == 'ERROR':
            jobs.append((t, s))
        if nm == 'firstrun.run':
            jobs.append((t, s))
def pay(js):
    t, s = js
    d = run(f"traces payload {t['traceId']} {s['spanId']} --fields input,output")
    f = (d or {}).get('data', {}).get('fields', {})
    def g(k):
        try: return json.loads(f[k]['value'])
        except Exception: return None
    return {'trace': t['traceId'], 'tags': t.get('tags'), 'session': t.get('sessionId'), 'start': t['startedAt'], 'span': s['spanId'], 'name': s.get('name'), 'input': g('input'), 'output': g('output')}
with F.ThreadPoolExecutor(8) as ex:
    out = list(ex.map(pay, jobs))
json.dump(out, open(S + '/steps.json', 'w'))
print(len(T), len(jobs))
EOF
